style.css:
@-moz-document domain("youtube.com") {
:root {
    --bg: #F5F0E6;
    --card: #FDF9F2;
    --text: #4A3F35;
    --text2: #7A6B5D;
    --border: #E8DFD0;
    --chip-bg: #EFE8DC;
  }

  /* Fondo general */
  html, body, ytd-app, #content, ytd-page-manager, #page-manager,
  ytd-browse, #columns, #primary {
    background-color: var(--bg) !important;
    color: var(--text) !important;
  }

  /* Header */
  ytd-masthead, #masthead-container, #background {
    background-color: var(--bg) !important;
    border-bottom: 1px solid var(--border) !important;
  }

  /* Sidebar */
  #guide-content, ytd-guide-renderer, #sections {
    background-color: var(--bg) !important;
  }

  /* ========== BARRA DE FILTROS (Todos, Música, etc.) ========== */
  ytd-feed-filter-chip-bar-renderer,
  #chips-wrapper,
  #header.ytd-rich-grid-renderer {
    background-color: var(--bg) !important;
  }

  yt-chip-cloud-chip-renderer {
    background-color: var(--chip-bg) !important;
    border-radius: 20px !important;
    margin: 0 6px !important;
  }

  yt-chip-cloud-chip-renderer[selected] {
    background-color: #E0D5C5 !important;
  }

  yt-chip-cloud-chip-renderer #text {
    color: var(--text) !important;
  }

  /* ========== CARDS DE VIDEOS ========== */
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-compact-video-renderer,
  ytd-grid-video-renderer {
    background-color: var(--card) !important;
    border-radius: 16px !important;
    overflow: hidden !important;
    border: 1px solid var(--border) !important;
    margin-bottom: 18px !important;
  }

  /* Padding interno importante (esto arregla los iconos y títulos pegados) */
  ytd-rich-grid-media #dismissible,
  ytd-video-renderer #dismissible,
  ytd-compact-video-renderer #dismissible {
    padding: 12px 12px 14px 12px !important;
  }

  /* Miniaturas */
  ytd-thumbnail,
  #thumbnail {
    border-radius: 12px !important;
    overflow: hidden !important;
    margin-bottom: 10px !important;
  }

  ytd-thumbnail img,
  #thumbnail img {
    border-radius: 12px !important;
    filter: brightness(1.04) saturate(0.9) sepia(0.06) !important;
  }

  /* ===== META (título + canal + vistas) ===== */
  #meta,
  ytd-video-meta-block,
  ytd-rich-grid-media #meta {
    padding: 0 4px 2px 4px !important;
  }

  /* Avatar del canal - más espacio */
  #avatar-link,
  ytd-channel-name yt-img-shadow,
  #channel-thumbnail,
  .yt-spec-avatar-shape,
  yt-img-shadow#avatar {
    margin-right: 10px !important;
    margin-left: 2px !important;
  }

  /* Título */
  #video-title {
    color: var(--text) !important;
    font-family: Georgia, "Times New Roman", serif !important;
    font-weight: 500 !important;
    padding: 2px 2px 4px 2px !important;
    line-height: 1.35 !important;
  }

  /* Textos secundarios */
  #metadata-line,
  #published-time-text,
  ytd-video-meta-block span,
  #byline-container {
    color: var(--text2) !important;
  }

  /* Reducir un poco el vacío de la derecha */
  ytd-rich-grid-renderer #contents {
    padding-right: 12px !important;
    padding-left: 8px !important;
  }

  ytd-rich-grid-row {
    margin-bottom: 8px !important;
  }
}
